#include<bits/stdc++.h>

using namespace std;

#define MAXP 300005

vector<long long> sieve(){
  vector<long long> res;
  vector<int> mem(MAXP,0);
  for(int i=2;i<MAXP;i++){
    if(mem[i]){continue;}
    res.push_back(i);
    for(int j=i;j<MAXP;j+=i){mem[j]=1;}
  }
  return res;
}

int main(){
  vector<long long> p=sieve();
  long long n;
  cin >> n;
  int sz=p.size();
  int res=0;
  for(int i=0;i<sz;i++){
    int k=sz-1;
    for(int j=i+1;j<k && j<sz;j++){
      while(j<k){
        long long v=p[i]*p[i]*p[j]; // <= 10^{18}, won't overflow
        if(v>n){k--;continue;}
        v*=p[k]; // <= 10^{18} because (<= n <= 10^12) * (<= 10^6)
        if(v>n){k--;continue;}
        v*=p[k];
        if(v>n){k--;continue;}
        break;
      }
      res+=(k-j);
    }
  }
  cout << res << "\n";
  return 0;
}

#include<bits/stdc++.h>

using namespace std;

#define MAXP 300005

vector<long long> sieve(){
  vector<long long> res;
  vector<int> mem(MAXP,0);
  for(int i=2;i<MAXP;i++){
    if(mem[i]){continue;}
    res.push_back(i);
    for(int j=i;j<MAXP;j+=i){mem[j]=1;}
  }
  return res;
}

int main(){
  vector<long long> p=sieve();
  long long n;
  cin >> n;
  int sz=p.size();
  int res=0;
  for(int i=0;i<sz;i++){
    for(int j=i+1;j<sz;j++){
      for(int k=j+1;k<sz;k++){
        long long v=p[i]*p[i]*p[j];
        if(v>n){break;}
        v*=p[k];
        if(v>n){break;}
        v*=p[k];
        if(v>n){break;}
        res++;
      }
    }
  }
  cout << res << "\n";
  return 0;
}

#include <iostream>
#include <string>
#include <vector>
using namespace std;

const long long Z = 1000000;
bool isprime[Z+1] = {};
int count_primes[Z+1] = {};
vector<long long> primes;


int main(){
    for(int p=2; p<=Z; p++) isprime[p] = true;
    for(int p=2; p*p<=Z; p++) if(isprime[p]){
        for(int q=p*p; q<=Z; q+=p) isprime[q] = false;
    }
    for(int p=2; p<=Z; p++) if(isprime[p]){
        primes.push_back(p);
        count_primes[p] = 1;
    }
    for(int p=2; p<=Z; p++) count_primes[p] += count_primes[p-1];

    long long N; cin >> N;
    long long ans = 0;
    for(long long a=2; a*a*a*a*a<=N; a++) if(isprime[a]) {
        for(long long c=a+1; a*a*a*c*c<=N; c++) if(isprime[c]) {
            long long br = min(c-1, N/(a*a*c*c));
            long long bl = a;
            if(bl < br) {
                ans += count_primes[br];
                ans -= count_primes[bl];
            }
        }
    }
    cout << ans << endl;
    return 0;
}
